import * as React from "react"

const MOBILE_BREAKPOINT = 768
const QUERY = `(max-width: ${MOBILE_BREAKPOINT - 1}px)`

function subscribe(onChange: () => void) {
  const mql = window.matchMedia(QUERY)
  mql.addEventListener("change", onChange)
  return () => mql.removeEventListener("change", onChange)
}

// Generated by shadcn, then rewritten with useSyncExternalStore: the original set state inside an
// effect, which this project's lint rules (react-hooks/set-state-in-effect) reject. Same export and
// behaviour: false on the server and during hydration, then the real value in the browser.
export function useIsMobile() {
  return React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(QUERY).matches,
    () => false
  )
}
